Command `cat > /workspace/test_multi.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <gzip_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *inbuf = malloc(fsize);
    fread(inbuf, 1, fsize, f);
    fclose(f);

    z_stream strm;
    memset(&strm, 0, sizeof(strm));

    int ret = inflateInit2(&strm, MAX_WBITS + 32);
    if (ret != Z_OK) {
        fprintf(stderr, "inflateInit2 failed: %d\n", ret);
        return 1;
    }

    strm.next_in = inbuf;
    strm.avail_in = fsize;

    // Simulate KTar: read 512 bytes at a time, multiple calls
    unsigned char outbuf[512];
    int total_out = 0;

    for (int i = 0; i < 100; i++) {
        memset(outbuf, 0xAB, 512);
        strm.next_out = outbuf;
        strm.avail_out = 512;

        ret = inflate(&strm, Z_SYNC_FLUSH);
        int written = 512 - strm.avail_out;
        total_out += written;
        printf("Call %d: inflate returned %d, written %d bytes, total_out %d\n", 
               i, ret, written, total_out);

        // Check for overflow
        for (int j = 512; j < 1024; j++) {
            if (outbuf[j] != 0xAB) {
                printf("OVERFLOW at call %d, offset %d: 0x%02x\n", i, j, outbuf[j]);
            }
        }

        if (ret != Z_OK) {
            printf("Done: %s\n", strm.msg ? strm.msg : "no error");
            break;
        }
    }

    inflateEnd(&strm);
    free(inbuf);
    return 0;
}
EOF
